"use strict";
import { useQuery } from "@tanstack/react-query";
import { ProtocolVersion } from "@uniswap/client-pools/dist/pools/v1/types_pb";
import { useAccount } from "hooks/useAccount";
import { useEthersProvider } from "hooks/useEthersProvider";
import { fetchAbstractV3CollectableFees } from "hooks/utils/fetchAbstractV3Fees";
import { mapSubgraphPositionToPositionInfo } from "./utils/positionMapper";
import { getAbstractSubgraphs } from "uniswap/src/constants/abstractContracts";
const GET_POSITION = `
  query GetPosition($positionId: String!) {
    position(id: $positionId) {
      id
      protocol
      status

      # Owner info
      user {
        id
      }

      # Token info
      token0 {
        id
        symbol
        name
        decimals
        derivedETH
        derivedUSD
      }
      token1 {
        id
        symbol
        name
        decimals
        derivedETH
        derivedUSD
      }

      # V2 fields
      balance
      stable
      token0Amount
      token1Amount
      token0AmountUnstaked
      token1AmountUnstaked
      shareOfPool

      # V3 fields
      tokenId
      liquidity
      tickLower
      tickUpper
      tickSpacing
      fee
      feeGrowthInside0LastX128
      feeGrowthInside1LastX128
      tokensOwed0
      tokensOwed1
      token0AmountCurrent
      token1AmountCurrent
      unclaimedFeesToken0
      unclaimedFeesToken1
      minPrice
      maxPrice
      currentPrice
      inRange

      # USD values
      totalValueUSD
      unstakedValueUSD

      # Pool references
      v2Pool {
        id
        token0 { id symbol decimals }
        token1 { id symbol decimals }
        stable
        totalSupply
        reserve0
        reserve1
        reserveUSD
        gauge {
          id
          isAlive
          totalWeight
          bribeContract
          feeContract
          # v2.3.0+ Reward distribution data
          rewardRate
          emissions
          periodFinish
          lastUpdateTime
          rewardPerTokenStored
          totalStaked
          totalValueLockedUSD
          stakerCount
        }
      }
      v3Pool {
        id
        token0 { id symbol decimals }
        token1 { id symbol decimals }
        fee
        tickSpacing
        liquidity
        sqrtPriceX96
        tick
        price
        totalValueLockedUSD
        clGauge {
          id
          isAlive
          totalWeight
          bribeContract
          feeContract
          # v2.3.0+ Reward distribution data
          rewardRate
          emissions
          periodFinish
          lastUpdateTime
          totalStakedLiquidity
          totalValueLockedUSD
          stakerCount
        }
      }

      # Staking info
      staked {
        id
        isStaked
        stakedAmount
        stakedToken0Amount
        stakedToken1Amount
        stakedValueUSD
        # v2.3.0+ User reward tracking
        userRewardPerTokenPaid
        pendingRewards
        lastRewardUpdate
        v2Gauge {
          id
          isAlive
          totalWeight
          bribeContract
          feeContract
          # v2.3.0+ Reward distribution data
          rewardRate
          emissions
          periodFinish
          lastUpdateTime
          rewardPerTokenStored
          totalStaked
          totalValueLockedUSD
          stakerCount
        }
        v3Gauge {
          id
          isAlive
          totalWeight
          bribeContract
          feeContract
          # v2.3.0+ Reward distribution data
          rewardRate
          emissions
          periodFinish
          lastUpdateTime
          totalStakedLiquidity
          totalValueLockedUSD
          stakerCount
        }
        stakedAt
        totalEmissionsClaimed
      }

      # Metadata
      createdAt
      createdAtBlock
      updatedAt
      updatedAtBlock
    }
  }
`;
async function fetchPosition(positionId, chainId) {
  const subgraphs = getAbstractSubgraphs(chainId);
  const url = subgraphs.positions;
  try {
    const response = await fetch(url, {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        query: GET_POSITION,
        variables: {
          positionId
        }
      })
    });
    if (!response.ok) {
      throw new Error(`Subgraph request failed: ${response.status}`);
    }
    const result = await response.json();
    if (result.errors) {
      console.error("\u274C [POSITION] Subgraph errors:", result.errors);
      throw new Error("Subgraph query returned errors");
    }
    if (!result.data?.position) {
      console.log(`\u2139\uFE0F [POSITION] No position found for ID: ${positionId}`);
      return null;
    }
    console.log(`\u2705 [POSITION] Fetched position ${positionId}`);
    return result.data.position;
  } catch (error) {
    console.error("\u274C [POSITION] Fetch failed:", error);
    throw error;
  }
}
export function useAbstractPosition(tokenId, chainId) {
  const account = useAccount();
  const provider = useEthersProvider({ chainId });
  return useQuery({
    queryKey: ["abstract-position", tokenId, chainId, account.address, Boolean(provider)],
    queryFn: async () => {
      if (!tokenId || !account.address) {
        return null;
      }
      try {
        const positionId = `v3-${tokenId}`;
        console.log(`\u{1F50D} [POSITION] Fetching position ${positionId} for user ${account.address}`);
        const subgraphPosition = await fetchPosition(positionId, chainId);
        if (!subgraphPosition) {
          console.log(`\u274C [POSITION] Position ${positionId} not found`);
          return null;
        }
        let positionInfo;
        try {
          positionInfo = mapSubgraphPositionToPositionInfo(subgraphPosition, chainId);
        } catch (mappingError) {
          console.error(`\u274C [POSITION] Error mapping position ${positionId}:`, mappingError, subgraphPosition);
          return null;
        }
        if (positionInfo?.version === ProtocolVersion.V3 && provider) {
          const feeUpdate = await fetchAbstractV3CollectableFees({
            provider,
            chainId,
            tokenId: positionInfo.tokenId,
            ownerAddress: positionInfo.owner,
            recipientAddress: account.address,
            gaugeAddress: positionInfo.gaugeAddress
          });
          if (feeUpdate) {
            positionInfo = {
              ...positionInfo,
              token0UncollectedFees: feeUpdate.amount0,
              token1UncollectedFees: feeUpdate.amount1
            };
          }
        }
        console.log(`\u2705 [POSITION] Successfully mapped position ${positionId}`, {
          status: positionInfo.status,
          isStaked: positionInfo.isStaked,
          gaugeAddress: positionInfo.gaugeAddress,
          tvlUSD: positionInfo.tvlUSD
        });
        return {
          ...positionInfo,
          // Ensure these fields exist for backward compatibility
          isHidden: false
        };
      } catch (error) {
        console.error(`\u274C [POSITION] Error fetching position ${tokenId}:`, error);
        return null;
      }
    },
    enabled: !!tokenId && !!account.address,
    refetchInterval: 3e4
    // Refetch every 30 seconds
  });
}
